<?php
declare(strict_types=1); require dirname(__DIR__,2).'/includes/bootstrap.php'; require_permission('video_categories.manage');
$rows=db()->query("SELECT c.id,c.name,c.character_name,c.capacity_limit,c.status,COUNT(DISTINCT q.id) total_qr,COALESCE(SUM(q.status='ACTIVE'),0) active_qr,COALESCE(SUM(q.status IN ('INACTIVE','EXPIRED')),0) pending_qr,COUNT(DISTINCT s.spot_id) spots FROM video_categories c LEFT JOIN qr_campaigns q ON q.category_id=c.id LEFT JOIN spot_campaigns s ON s.category_id=c.id GROUP BY c.id ORDER BY c.name")->fetchAll();$pageTitle='Category summary';$pageSubtitle='QR inventory and campaign health by category';require APP_ROOT.'/includes/header.php';
?><section class="panel"><div class="table-wrap"><table><thead><tr><th>Category</th><th>Character</th><th>Total QR</th><th>Active QR</th><th>Pending / inactive</th><th>Spots</th><th>Capacity</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong></td><td><?=e($r['character_name']??'—')?></td><td><?=e($r['total_qr'])?></td><td><span class="badge active"><?=e($r['active_qr'])?></span></td><td><span class="badge pending"><?=e($r['pending_qr'])?></span></td><td><?=e($r['spots'])?></td><td><?=e($r['total_qr'])?> / <?=e($r['capacity_limit'])?></td><td><span class="badge <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td></tr><?php endforeach?></tbody></table><?php if(!$rows):?><div class="empty">No categories configured.</div><?php endif?></div></section><?php require APP_ROOT.'/includes/footer.php';
